import json
import re
import shutil
import subprocess
from pathlib import Path
EXPORT_SCRIPT = '/opt/payroll/bin/export_payroll.py'
DEPT_REGISTRY = '/opt/payroll/config/departments.json'

def run_payroll_export_and_archive(pay_period: str, department: str, export_dir: str, archive_root: str) -> dict:
    if not re.fullmatch('\\d{4}-(0[1-9]|1[0-2])', pay_period or ''):
        return {'ok': False, 'error': 'pay_period must be YYYY-MM'}
    if not re.fullmatch('[A-Z]{2,10}', department or ''):
        return {'ok': False, 'error': 'department must be an uppercase code'}
    registry_file = Path(DEPT_REGISTRY)
    if registry_file.is_file():
        try:
            registry = json.loads(registry_file.read_text())
        except (OSError, ValueError):
            registry = {}
        known = registry.get('departments', [])
        if known and department not in known:
            return {'ok': False, 'error': 'unknown department code'}
    export_path = Path(export_dir)
    if not export_path.is_dir():
        return {'ok': False, 'error': 'export_dir does not exist'}
    archive_path = Path(archive_root)
    if not archive_path.is_dir():
        return {'ok': False, 'error': 'archive_root does not exist'}
    result = subprocess.run(['python3', EXPORT_SCRIPT, '--period', pay_period, '--dept', department, '--out', str(export_path)], capture_output=True, text=True, timeout=600)
    if result.returncode != 0:
        return {'ok': False, 'error': result.stderr.strip()[:500]}
    produced = export_path / f'payroll_{department}_{pay_period}.csv'
    if not produced.exists():
        return {'ok': False, 'error': 'export finished but no file was produced'}
    target_dir = archive_path / pay_period
    target_dir.mkdir(parents=True, exist_ok=True)
    target = target_dir / produced.name
    if target.exists():
        return {'ok': False, 'error': 'archive file already exists'}
    shutil.move(str(produced), str(target))
    return {'ok': True, 'archived_to': str(target)}
